  Future<void> _submitOffer()async{final uid=FirebaseAuth.instance.currentUser?.uid;final request=_request;final price=double.tryParse(_price.text.trim());if(uid==null||request==null||price==null||price<=0){_snack(tx('اكتب سعر الشيفت بشكل صحيح','Enter a valid shift price'));return;}if(request.status!='open'){_snack(tx('الطلب لم يعد متاحاً للتقديم','This request is no longer available'));return;}if(_alreadyApplied){_snack(tx('أنت قدمت عرضًا بالفعل على هذا الطلب','You already submitted an offer for this request'));return;}setState(()=>_sending=true);try{final db=FirebaseFirestore.instance;final requestRef=db.collection('careRequests').doc(request.id);final offerRef=db.collection('careOffers').doc('${request.id}_$uid');final userSnap=await db.collection('users').doc(uid).get();final profileSnap=await db.collection('nurseProfiles').doc(uid).get();await db.runTransaction((transaction)async{final requestSnap=await transaction.get(requestRef);final existingOffer=await transaction.get(offerRef);if(!requestSnap.exists||requestSnap.data()?['status']!='open')throw Exception('closed');if(existingOffer.exists)throw Exception('duplicate');final userData=userSnap.data()??{};final profile=profileSnap.data()??{};transaction.set(offerRef,{'requestId':request.id,'clientId':request.clientId,'nurseId':uid,'nurseName':userData['name']??(en?'Nurse':'ممرض'),'nursePhotoUrl':userData['photoUrl'],'nurseRating':(profile['averageRating'] as num?)?.toDouble()??0,'nurseExperienceYears':profile['experienceYears']??0,'nurseSpecialization':profile['specialization']??'','nurseVerified':userData['isVerified']==true,'governorate':request.governorate,'proposedPrice':price,'note':_note.text.trim(),'status':'pending','createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});});if(mounted){setState((){_alreadyApplied=true;_sending=false;});_snack(tx('تم إرسال عرضك للعميل بنجاح','Your offer was sent to the client successfully'));}}catch(e){if(mounted){setState(()=>_sending=false);_