  @override Widget build(BuildContext context){if(_loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));final r=_request;if(r==null)return Scaffold(appBar:AppBar(title:Text(tx('تفاصيل الطلب','Request details'))),body:Center(child:Text(tx('الطلب غير موجود أو لم يعد متاحًا','Request not found or no longer available'))));final locale=en?'en_US':'ar_EG';return Scaffold(appBar:AppBar(title:Text(tx('تفاصيل الطلب','Request details'))),body:RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),physics:const AlwaysScrollableScrollPhysics(),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(tx('طلب رعاية','Care request'),style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),_row(tx('نوع الرعاية','Care type'),_careType(r.careType)),_row(t('age'),'${r.patientAge} ${tx('سنة','years')}'),_row(t('gender'),r.patientGender=='male'?tx('ذكر','Male'):tx('أنثى','Female')),_row(tx('الشيفت','Shift'),'${r.shiftHours} ${t('hours_short')} × ${r.daysCount} ${t('days_short')}'),_row(t('date'),DateFormat('d/M/yyyy',locale).format(r.startDate)),_row(t('governorate'),_governorate(r.governorate)),_row(t('area'),r.area),if(r.services.isNotEmpty)...[const SizedBox(height:8),Text(r.services.map(_service).join(' • '),style:const TextStyle(color:AppColors.textSecondary))],if(r.notes?.isNotEmpty==true)...[const SizedBox(height:10),Text(r.notes!)] ]))),const SizedBox(height:16),if(_alreadyApplied)Card(color:AppColors.primaryLight,child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[const Icon(Icons.check_circle,color:AppColors.primary),const SizedBox(width:10),Expanded(child:Text(tx('قدمت عرضك بالفعل. انتظر اختيار العميل.','You already submitted an offer. Wait for the client to choose.')))]))) else if(r.status=='open')...[Text(tx('قدم عرضك','Submit your offer'),style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),TextField(controller:_price,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:tx('سعر الشيفت المقترح','Proposed shift price'),suffixText:t('currency_egp'),prefixIcon:const Icon(Icons.payments_outlined))),const SizedBox(height:12),TextField(controller:_note,maxLines:3,decoration:InputDecoration(labelText:tx('رسالة للعميل (اختياري)','Message to client (optional)'),alignLabelWithHint:true,prefixIcon:const Icon(Icons.message_outlined))),const SizedBox(height:16),SizedBox(height:52,child:FilledButton(onPressed:_sending?null:_submitOffer,child:_sending?const SizedBox(width:22,height:22,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):Text(tx('إرسال العرض','Send offer'))))] else Card(child:Padding(padding:const EdgeInsets.all(18),child:Text(tx('هذا الطلب لم يعد متاحاً للتقديم.','This request is no longer available for offers.')))])));}
  Widget _row(String label,String value)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:95,child:Text(label,style:const TextStyle(fontWeight:FontWeight.bold))),Expanded(child:Text(value))]));
  String _careType(String v){final k={'elderly':'care_elderly','post_surgery':'care_post_surgery','chronic_disease':'care_chronic','disability':'care_disability','maternity':'care_maternity','general':'care_general'}[v];return k==null?v:t(k);}
  String _service(String v){final k={'متابعة الحالة':'service_followup','إعطاء الأدوية':'service_medication','قياس الضغط':'service_bp','قياس السكر':'service_glucose','تغيير الجروح':'service_wound','مساعدة الحركة':'service_mobility','رعاية كبار السن':'service_elderly','رعاية ما بعد العمليات':'service_post_surgery'}[v];return k==null?v:t(k);}
  String _governorate(String v){const enMap={'القاهرة':'Cairo','الجيزة':'Giza','الإسكندرية':'Alexandria','القليوبية':'Qalyubia','الدقهلية':'Dakahlia','الشرقية':'Sharqia','الغربية':'Gharbia','المنوفية':'Monufia','البحيرة':'Beheira','كفر الشيخ':'Kafr El Sheikh','دمياط':'Damietta','بورسعيد':'Port Said','الإسماعيلية':'Ismailia','السويس':'Suez','الفيوم':'Fayoum','بني سويف':'Beni Suef','المنيا':'Minya','أسيوط':'Assiut','سوهاج':'Sohag','قنا':'Qena','الأقصر':'Luxor','أسوان':'Aswan','مطروح':'Matrouh','الوادي الجديد':'New Valley','شمال سيناء':'North Sinai','جنوب سيناء':'South Sinai','البحر الأحمر':'Red Sea'};return en?(enMap[v]??v):v;}
